package com.casestudy.insurancecampaign.auth.model.dto.request;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * Request payload used to reset a user's password.
 *
 * @param resetToken password reset token generated by forgot-password operation
 * @param newPassword new raw password that will be encoded before persistence
 */
public record ResetPasswordRequest(
        @NotBlank String resetToken,
        @NotBlank @Size(min = 8, max = 100) String newPassword
) { }
